# add the static helpers before "## The name a report gives"
anchor="## The name a report gives what an aim is on"
helpers='''## What a swing's landing does to the wood `tg` (model `wood`, frame `to_world`) it was aimed at: {hit, plan, reason}. The
## head flew the arc fixed at the release and stops where it meets the wood NOW (AxeSwing.contact from 25 deg before the
## planned contact: another blow may have opened it meanwhile), the plan (AxeSwing.plan) says what leaves. `reason` is ""
## when the blow takes wood; else why not (every wood blow that crossed material removes volume or names it):
## no_contact_at_landing (hit is {}), jam_cheek / jam_haft (a cheek / the haft met wood before the edge and the kerf is
## too narrow for the head), jam_eye (the eye stopped the head at once), energy (the edge touched with too little to
## clear a cell). Shared by _strike, _wood_strike and the edge oracle test.
static func wood_blow(aim: Dictionary, tg: Dictionary, wood: WoodCuts, to_world: Transform3D, e: float, tool: Dictionary,
		spec: Dictionary) -> Dictionary:
	var hit := AxeSwing.contact(aim.sw, [tg], rad_to_deg(float(aim.th)) + 25.0)
	if hit.is_empty():
		return {"hit": hit, "plan": {}, "reason": "no_contact_at_landing"}
	var b := AxeSwing.plan(hit, wood, to_world, e, tool, spec)
	var why := ""
	if (b.pieces as Array).is_empty():
		match int(hit.probe):
			1:
				why = "jam_cheek"
			2:
				why = "jam_haft"
			_:
				why = "jam_eye" if float(b.limit) <= 1e-4 else "energy"
	return {"hit": hit, "plan": b, "reason": why}


# A blow that took no wood says why (autotest runs and the browser log it: the bots and Maxim's playtests can see them).
static func _noeffect(reason: String, kind: String, id: int, aim: Dictionary, tool: Dictionary, hit := {}) -> void:
	var sw: Dictionary = aim.get("sw", {})
	print("CHOP_NOEFFECT reason=%s target=%s id=%d tool=%s probe=%d th=%.1fdeg radius=%.3f kept=%s" % [reason, kind, id,
		String(tool.get("name", "?")), int(hit.get("probe", -1)), rad_to_deg(float(aim.get("th", 0.0))),
		float(sw.get("radius", 0.0)), str(aim.get("kept", false))])


'''
assert anchor in s
s=s.replace(anchor,helpers+anchor,1)
open(p,'w').write(s)
