## 7 overhead strikes at one spot: the first looks at `top`, the next ones at `drop` x the notch's depth below it.
func _memory_run(label: String, tg: Dictionary, tool: Dictionary, st: Dictionary, top: Vector3, drop: float) -> Dictionary:
	var e := Impact.energy(tool, Physique.at(Physique.DEFAULT), 1.0)
	var look0: Vector3 = (top - (st.eye as Vector3)).normalized()
	var mem := {}
	var depth := 0.0
	var radius0 := -1.0
	var all_cut := true
	var line := ""
	for i in 7:
		var p := top - Vector3(0.0, drop * depth, 0.0)         # the cursor slides into the notch
		var look: Vector3 = ((p - (st.eye as Vector3)).normalized()) if i > 0 else look0
		var moved := rad_to_deg(look.angle_to(look0))
		var sw := ChopSystem.fit_wood([tg], st.body, st.yaw, st.crouch, st.eye, look, st.right, tool, 90.0, mem, 0.0)
		var aim := ChopAim.resolve_arc(sw.sw, [tg])
		var found: bool = aim.kind != ChopAim.Kind.NONE
		var removed := 0.0
		var reason := "no_contact"
		var probe := -1
		var jam := false
		if found:
			aim["tk"] = ChopSystem.tool_key(tool)
			aim["kept"] = sw.get("kept", false)
			probe = int(aim.probe)
			jam = bool(aim.jam)
			var bl := ChopSystem.wood_blow(aim, tg, tg.model, tg.frame, e, tool, func() -> Dictionary: return tg.spec)
			reason = String(bl.reason)
			if not (bl.hit as Dictionary).is_empty():
				var adv := float((bl.plan as Dictionary).advance)
				removed = WoodFixture.apply(tg, bl.plan)
				depth += adv
			mem = ChopSystem.strike_memory(aim, look)
		else:
			mem = {}
		var radius := float(sw.sw.radius)
		if i == 0:
			radius0 = radius
		var cut := found and removed > 0.0 and not (probe == 2 and jam)
		all_cut = all_cut and cut
		line += " [%d look+%.1fdeg r=%.3f kept=%s probe=%d jam=%s removed=%.1fcm3 %s]" % [i, moved, radius, str(sw.get("kept", false)), probe,
			str(jam), removed * 1e6, reason]
		_check("memory_%s_strike%d_cuts" % [label, i], cut, "look %.1f deg off, radius %.3f, probe %d jam %s, %.1f cm3, %s" % [moved, radius, probe,
			str(jam), removed * 1e6, reason])
		if i > 0:
			_check("memory_%s_strike%d_radius_kept" % [label, i], absf(radius - radius0) < 1e-6, "%.3f vs the first %.3f" % [radius, radius0])
		await get_tree().physics_frame
	print("FEEL_MEMORY_%s%s" % [label.to_upper(), line])
	return {"all_cut": all_cut}


func _memory_end(tool: Dictionary, st: Dictionary, top: Vector3) -> void:
	var look0: Vector3 = (top - (st.eye as Vector3)).normalized()
'''
