				for uv: Vector2 in sf[2]:
					meshes += 1
					if absf(uv.x - R) > 1e-6 or uv.y != 2.0:
						fails += 1
						print("BOARD_SEAM FAIL operand uv=%s want (%.4f, 2)" % [str(uv), R])
						break
	print("BOARD_SEAM board %.0fx%.0f mm zone %.3f..%.3f operands=%d" % [w * 1000.0, t * 1000.0, z.x, z.y, meshes])
	var seg := Rod.box_segment(half, z.x, z.y)
	var worst := 0.0
	var at := ""
	for face in [Vector3.RIGHT, Vector3.LEFT, Vector3.BACK, Vector3.FORWARD]:
		for dy in [-0.06, -0.02, -0.005, 0.0, 0.005, 0.02, 0.06]:
