func _boulder() -> RockNode:
	var best: RockNode
	var bd := INF
	for f in get_tree().get_nodes_in_group("rock_fields"):
		for r: RockNode in f.rocks.values():
			if is_instance_valid(r) and r.is_inside_tree() and r.size > 0.4:
				var d := r.global_position.distance_to(_me.global_position)
				if d < bd:
					bd = d
